"use client"

import * as React from "react"

import { type Partition, type ViewerAdapter, toPageGroups } from "@/lib/retab"
import { meanLikelihood } from "@/hooks/use-retab"
import {
  RetabViewerShell,
  useViewerPhase,
} from "@/components/ui/retab-viewer-shell"
import { PageGroupViewer } from "@/components/ui/page-group-viewer"
import { RetabSourcePreview } from "@/components/ui/retab-source-preview"

export interface PartitionViewerProps {
  partition: Partition
  /** Optional adapter; when it resolves a document URL a source preview is shown. */
  adapter?: ViewerAdapter
  className?: string
}

export function PartitionViewer({
  partition,
  adapter,
  className,
}: PartitionViewerProps) {
  const chunks = partition.output ?? []
  const phase = useViewerPhase({
    status: partition.status,
    error: partition.error,
    hasOutput: chunks.length > 0,
  })
  const groups = React.useMemo(() => toPageGroups(chunks), [chunks])
  const confidences = partition.consensus?.likelihoods?.map((l) =>
    meanLikelihood(l.pages)
  )

  return (
    <RetabViewerShell
      title={partition.file?.filename ?? "Partition"}
      status={partition.status}
      error={partition.error}
      phase={phase}
      emptyMessage="No chunks were produced."
      className={className}
    >
      <PageGroupViewer groups={groups} unitLabel="chunk" confidences={confidences} />
      {adapter ? (
        <div className="px-4 pb-4">
          <RetabSourcePreview adapter={adapter} file={partition.file} />
        </div>
      ) : null}
    </RetabViewerShell>
  )
}

export { type Partition }
